-- ─── Fleet (6 boats) ────────────────────────────────────────────────────────

insert into boats (slug, name, description, capacity, power, length_m, day_rate, skipper_rate, sort_order, active) values
  ('featherbed-flyer', 'Featherbed Flyer',
   'A nimble centre-console built for the lagoon. Easy to handle, quick between the Heads and the Featherbed shoreline, and comfortable enough to spend a full day aboard. Bimini shade, boarding ladder and a dry storage locker forward.',
   6, '90 hp four-stroke outboard', 5.5, 3950, 1450, 1, true),

  ('thesen-tide', 'Thesen Tide',
   'Our family favourite. A broad, stable hull with generous seating, a deep cockpit and a swim platform aft — the boat we point people to when there are children aboard or a picnic to lay out.',
   8, '115 hp four-stroke outboard', 6.2, 4600, 1450, 2, true),

  ('leisure-isle-lady', 'Leisure Isle Lady',
   'A classic day boat with a soft ride and an unhurried temperament. Ideal for a slow circuit of Leisure Isle, an afternoon on the sandbanks, and sundowners on the way back to the moorings.',
   6, '75 hp four-stroke outboard', 5.2, 3650, 1450, 3, true),

  ('heads-runner', 'Heads Runner',
   'The most capable hull in the fleet and the one we recommend for anyone heading out through the Heads on a settled day. Deep-V forward, self-draining cockpit, and rails you will be glad of in a chop.',
   6, '150 hp four-stroke outboard', 6.0, 5900, 1450, 4, true),

  ('lagoon-lark', 'Lagoon Lark',
   'Small, light and genuinely fun. Two or three people, a cooler box and a whole day of shallow water to explore. The cheapest way onto the lagoon and often the first boat off the moorings.',
   4, '60 hp four-stroke outboard', 4.6, 2950, 1450, 5, true),

  ('belvidere-belle', 'Belvidere Belle',
   'A refined cruiser for a quieter kind of day. Upholstered seating, a proper table, shade over the whole cockpit and enough range to work the top of the lagoon up towards Belvidere and back at an easy pace.',
   8, '2 × 70 hp four-stroke outboards', 6.8, 6400, 1450, 6, true)
on conflict (slug) do nothing;

-- ─── Auto-reply templates ───────────────────────────────────────────────────
-- Placeholders: {name} {boat} {date} {deposit} {balance} {total} {method}
--               {reference} {link} {bank_details}

insert into message_templates (key, subject, body) values
  ('received',
   'We have your booking request — {reference}',
   E'Hi {name},\n\nThank you for your booking request with Knysna Boat Rentals.\n\n  Boat:      {boat}\n  Date:      {date}\n  Reference: {reference}\n  Day total: R{total}\n  Deposit:   R{deposit} ({method})\n\nA 50% deposit secures the date. The balance of R{balance} is payable on collection.\n\nYou can view your booking, pay the deposit, sign the indemnity and upload your documents here:\n{link}\n\n{bank_details}\n\nWe will be in touch shortly to confirm the details.\n\nKind regards,\nKnysna Boat Rentals'),

  ('deposit',
   'Reminder: deposit outstanding for {reference}',
   E'Hi {name},\n\nA friendly reminder that the deposit of R{deposit} for {boat} on {date} is still outstanding. The date is held for you until the deposit reflects.\n\nYou can pay or view the banking details here:\n{link}\n\n{bank_details}\n\nKind regards,\nKnysna Boat Rentals'),

  ('docs',
   'Documents needed before your trip on {date}',
   E'Hi {name},\n\nYour trip on {boat} is coming up on {date}. Before you can collect the boat we still need:\n\n  • A copy of your ID or passport\n  • Your SAMSA skipper''s licence (self-drive hires only)\n  • The signed indemnity, waiver and release\n\nYou can upload everything and sign online here:\n{link}\n\nWithout a signed indemnity we are not able to release the boat, and the deposit is not refundable in that case.\n\nKind regards,\nKnysna Boat Rentals'),

  ('confirmed',
   'Your booking is confirmed — {reference}',
   E'Hi {name},\n\nYour booking is confirmed.\n\n  Boat:      {boat}\n  Date:      {date}\n  Reference: {reference}\n  Paid:      R{deposit}\n  Balance:   R{balance} on collection\n\nPlease arrive 30 minutes before your departure time for the handover and safety briefing, and bring the original of the ID and skipper''s licence you uploaded.\n\nWe look forward to seeing you on the water.\n\nKind regards,\nKnysna Boat Rentals')
on conflict (key) do nothing;

-- ─── Owner-editable site copy ───────────────────────────────────────────────

insert into site_content (key, title, body) values
  ('terms', 'Rental Terms & Conditions',
E'## 1. Booking and payment\n\nAll hires are charged at a full-day rate. A deposit of 50% of the total hire fee (day rate plus skipper fee, where a skipper is booked) is required to secure a date. The balance is payable on collection, by card or EFT. Bookings are held provisionally for 48 hours from the time of request; if the deposit has not reflected by then we may release the date.\n\n## 2. Security deposit\n\nA refundable security deposit is taken on collection and is held against damage, loss of equipment and fuel. It is refunded in full once the boat has been returned and inspected. The amount depends on the vessel and is confirmed at the time of booking.\n\n## 3. Fuel\n\nBoats are supplied with a full tank and must be returned full, or the fuel used will be charged at the prevailing pump rate plus a handling fee.\n\n## 4. Skipper''s licence\n\nSelf-drive hires require a valid SAMSA skipper''s licence (Category R or higher, as appropriate to the vessel and area of operation). The original must be produced on collection. If you do not hold a licence, a skipper must be booked with the boat.\n\n## 5. Cancellation\n\nCancellations more than 14 days before the hire date: deposit refunded less a 10% administration fee. Between 14 and 7 days: 50% of the deposit is refunded. Less than 7 days: the deposit is forfeited. If we cancel because of weather or a mechanical fault, you may choose a full refund of monies paid or an alternative date.\n\n## 6. Weather\n\nThe skipper on duty, or the operator, may cancel or curtail a hire on safety grounds. Where a hire is cancelled by us before departure, clause 5 applies. Once a trip has begun, no refund is due for a shortened outing.\n\n## 7. Area of operation\n\nSelf-drive hires are restricted to the Knysna estuary. Passage through the Heads is not permitted on a self-drive hire under any circumstances. Sea passage is available only with one of our skippers aboard and only in suitable conditions.\n\n## 8. Conduct on board\n\nThe hirer is responsible for everyone on board. Life jackets must be worn by all children and by all persons under way in the vicinity of the Heads. The operation of a vessel under the influence of alcohol or drugs is an offence and will end the hire immediately with no refund. Maximum capacity may not be exceeded.\n\n## 9. Damage and loss\n\nThe hirer is liable for damage to the vessel, motor, trailer and equipment arising from negligence, misuse, grounding or operation outside the permitted area, to the extent permitted by law. This includes loss of use while repairs are carried out.\n\n## 10. Indemnity\n\nEvery person going aboard must sign the Indemnity, Waiver and Release. Where a person is under 18, a parent or legal guardian must sign on their behalf. No signature, no trip, and no refund.\n\n## 11. Personal information\n\nWe collect and process personal information in line with our Privacy Notice and the Protection of Personal Information Act, 2013.'),

  ('indemnity', 'Indemnity, Waiver & Release',
E'**Please read this document carefully. It affects your legal rights.**\n\n## 1. Acknowledgement of risk\n\nI understand that boating on the Knysna estuary and at sea is a hazardous activity. Risks include, but are not limited to: collision, grounding, capsize, sinking, fire, explosion, mechanical failure, sudden changes in weather, strong currents and tidal flows — particularly in the vicinity of the Knysna Heads — falling overboard, drowning, hypothermia, sunburn, injury from the vessel, its motor, propeller or equipment, the acts or omissions of other persons aboard, and the acts or omissions of other vessels and their operators. I acknowledge that assistance may be delayed and that medical facilities are not immediately available on the water.\n\n## 2. Assumption of responsibility\n\nI voluntarily choose to go aboard with full knowledge of these risks and I assume them. I confirm that I am medically fit to do so, that I have disclosed any condition that may affect my safety or that of others, and that I am not under the influence of alcohol or any drug. Where I am the hirer, I accept responsibility for the safety and conduct of every person I bring aboard, for their compliance with the operator''s instructions and with all applicable maritime law and regulations, and for ensuring that life jackets are worn where required.\n\n## 3. Waiver, release and indemnity\n\nTo the fullest extent permitted by law, I waive any claim against, release and hold harmless Knysna Boat Rentals, its owners, employees, contractors and skippers (the "Operator") in respect of any loss, damage, injury, illness or death suffered by me or by any person or property in my care, arising from or in connection with the hire, howsoever caused, save where such loss arises from the Operator''s gross negligence or wilful misconduct, which cannot be and is not excluded.\n\nI further indemnify the Operator against any claim brought by a third party arising from my use of the vessel, including claims for damage to other vessels, moorings, property or the environment.\n\n## 4. Unlawful use, poaching and impoundment\n\nI undertake not to use the vessel for any unlawful purpose. I acknowledge in particular that the taking of marine resources without a valid permit — including abalone, crayfish and oysters — is a criminal offence, and that a vessel used in such an activity is liable to be seized and impounded by the authorities. Should the vessel be detained, impounded, forfeited or damaged as a result of any unlawful act committed by me or by any person aboard at my invitation, I indemnify the Operator in full against the value of the vessel and its equipment, all legal costs, and all loss of income for the period the vessel is unavailable.\n\n## 5. Persons under 18\n\nWhere a person going aboard is under the age of 18, this document must be signed by that person''s parent or legal guardian, who signs both personally and on behalf of the minor and who accepts the obligations set out above in respect of the minor.\n\n## 6. Consumer Protection Act\n\nThis document is a notice contemplated in section 49 of the Consumer Protection Act, 68 of 2008. Nothing in it excludes liability for gross negligence, and nothing in it limits any right you have that may not lawfully be limited.\n\n## 7. No signature, no trip\n\nThe Operator will not release the vessel to any person who has not signed this document. Where a hire cannot proceed for that reason, the hire is treated as a cancellation by the hirer on the day and no refund is due.\n\n## 8. Declaration\n\nI confirm that I have read and understood this document, that I have had the opportunity to ask questions about it, and that I sign it freely.'),

  ('banking', 'EFT / Banking Details',
E'Account name:  Knysna Boat Rentals\nBank:          [Bank name]\nAccount type:  Cheque / Current\nAccount no:    [Account number]\nBranch code:   [Branch code]\nReference:     your booking reference\n\nPlease use your booking reference as the payment reference and send proof of payment to bookings@yourdomain.co.za.'),

  ('privacy', 'Privacy Notice',
E'Knysna Boat Rentals collects and processes personal information in accordance with the Protection of Personal Information Act, 2013 (POPIA).\n\n**What we collect.** Your name, telephone number and email address when you make a booking request; a copy of your identity document and skipper''s licence where a hire requires it; your signed indemnity; and a record of payments made.\n\n**Why we collect it.** To process and manage your booking, to meet our legal obligations as a vessel operator, to verify that a self-drive hirer is licensed, and to contact you about your hire.\n\n**Who can see it.** Only the operator and authorised staff. Documents are stored in encrypted, access-controlled storage and are never published or shared with third parties, except where we are required by law to produce them.\n\n**How long we keep it.** Identity documents and licence copies are deleted 30 days after the hire date. Booking and payment records are retained for the period required by tax and maritime law.\n\n**Your rights.** You may request access to the personal information we hold about you, ask us to correct it, or ask us to delete it where we are not obliged to keep it. Write to the information officer at bookings@yourdomain.co.za.'),

  ('safety', 'On the water — safety',
E'The Knysna estuary is beautiful and, in places, genuinely dangerous. A few things everyone aboard should know.\n\n**The Heads.** The channel between the Heads is narrow, shallow in parts, and subject to a strong tidal stream and a swell that can stand up very quickly. It has claimed a great many boats. Self-drive hires may not pass through the Heads. If you want to go outside, book a skipper.\n\n**Tides.** Plan around the tide. The lagoon dries into extensive sandbanks at low water and a boat that is comfortably afloat at noon can be aground by three. Tide tables are posted at the moorings and we will go through them with you at handover.\n\n**Life jackets.** There is a jacket aboard for every person. Children must wear theirs at all times. Everyone should wear one when under way near the Heads or in a chop.\n\n**Speed and wake.** 8 knots inside the moorings, and slow past other vessels, swimmers, paddlers and the oyster beds. You are responsible for damage caused by your wake.\n\n**Weather.** A south-easter can turn the lagoon choppy in under an hour. If conditions deteriorate, head back. We would far rather you cut the day short than push on.\n\n**If something goes wrong.** Drop anchor if you are able, put jackets on everyone, and call us first — we are usually the fastest people to reach you. For a life-threatening emergency call the NSRI.'),

  ('emergency', 'Emergency numbers',
E'NSRI Knysna (Station 12)   |  087 094 9774\nNSRI Emergency (national)  |  087 094 9774\nSea Rescue / Maritime      |  112 (from a mobile)\nAmbulance / ER24           |  084 124\nPolice (SAPS Knysna)       |  044 302 6600\nKnysna Boat Rentals        |  [operator number]\n\nVerify these numbers before going live — they change.'),

  ('knysna', 'Knysna & the lagoon',
E'Knysna sits on a tidal estuary rather than a true lagoon, fed by the Knysna River and opened to the Indian Ocean through two sandstone cliffs — the Heads — that rise a hundred and fifty metres out of the water. It is the richest estuary in South Africa by species count, and on a still morning it is as pretty a piece of water as you will find anywhere on the coast.\n\n**Featherbed.** The western shore is a private nature reserve, forested to the waterline. The anchorage below it is sheltered in almost any wind and is the classic spot for lunch on the water.\n\n**Leisure Isle.** Sandy, shallow and warm on a rising tide. The eastern shore has the best swimming in the estuary and the sandbanks off the point are where half of Knysna spends a summer afternoon.\n\n**Thesen Islands.** A short run from the moorings, with canals to idle through and the waterfront for a drink at the end of the day.\n\n**Belvidere and the top of the estuary.** Quieter water, more birds, and the river narrowing between banks of milkwood. Worth the run up on a full tide.\n\n**The Heads.** Look, photograph, and stay inside unless you have one of our skippers aboard.')
on conflict (key) do nothing;
